import{_ as o,o as d,c as a,ae as t}from"./chunks/framework.YL6nI5ZP.js";const c="/docs/assets/architecture.D5vatMre.png",g=JSON.parse('{"title":"Arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/01-arquitectura.md","filePath":"es/explanation/01-arquitectura.md"}'),s={name:"es/explanation/01-arquitectura.md"};function r(n,e,i,l,p,u){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h1><p>El panorama general: una aplicación web solo-cliente para modelado hidráulico 2D, donde todo — el editor, el generador de mallas y el motor hidráulico SWMM — se ejecuta en el navegador.</p><h2 id="diseno-solo-cliente" tabindex="-1">Diseño solo-cliente <a class="header-anchor" href="#diseno-solo-cliente" aria-label="Permalink to &quot;Diseño solo-cliente&quot;">​</a></h2><p>Local SWMM es una <strong>aplicación web solo-cliente</strong> para modelado y simulación hidráulica 2D de redes de aguas lluvias y aguas servidas. Todo — el editor, el generador de mallas y el motor hidráulico SWMM — se ejecuta en el navegador. El motor de simulación es el motor <strong>OpenSWMM</strong> de HydroCouple compilado a <strong>WebAssembly</strong> con Emscripten.</p><p>La rama experimental agrega el módulo de tránsito superficial 2D (generación de mallas, acoplamiento 1D↔2D, marcher GPU WebGPU) sobre el editor de red 1D.</p><h2 id="propiedades-clave" tabindex="-1">Propiedades clave <a class="header-anchor" href="#propiedades-clave" aria-label="Permalink to &quot;Propiedades clave&quot;">​</a></h2><ul><li><strong>Sin backend.</strong> El único servidor es un trivial servidor de archivos estáticos + endpoint de salud (<code>server.py</code>). Sin base de datos, sin paso de build para la UI, sin bundler.</li><li><strong>Sin framework de UI.</strong> El frontend son ~15.000 líneas de JavaScript sin dependencias (scripts clásicos + IIFEs) con Mapbox GL JS como única librería runtime pesada.</li><li><strong>Hidráulica embebida en WASM.</strong> El motor OpenSWMM 6.0.0 está cross-compilado para <code>wasm32-emscripten</code> con dependencias C++ gestionadas por vcpkg (Eigen, HDF5, nlohmann-json, SUNDIALS).</li><li><strong>Dos backends de simulación.</strong> Una vía de motor WASM (1D + 1D/2D acoplado) y un backend <strong>experimental WebGPU</strong> que reimplementa el solver 2D explícito local-inercial como kernels de cómputo WGSL y lo ejecuta en paralelo al motor WASM.</li><li><strong>Dos generadores de mallas.</strong> Un generador legado basado en <code>poly2tri</code> y el pipeline de producción <strong>Triangle WASM de Shewchuk</strong> (npm <code>triangle-wasm</code>).</li></ul><h2 id="arquitectura-de-un-vistazo" tabindex="-1">Arquitectura de un vistazo <a class="header-anchor" href="#arquitectura-de-un-vistazo" aria-label="Permalink to &quot;Arquitectura de un vistazo&quot;">​</a></h2><p><img src="'+c+`" alt="Arquitectura de LocalSWMM"></p><p><strong>Flujo de datos (simulación):</strong> modelo (<code>Net</code>) → <code>inpExporter.generateInp()</code> → inyección opcional de secciones 2D (<code>Mesh2DInp.buildInput</code>) → string <code>.inp</code> → Worker → <code>FS.writeFile(&#39;/in.inp&#39;)</code> → <code>swmm_engine_open/initialize/start</code> → bucle <code>stride()</code> → lectura de <code>.rpt</code> + <code>.out</code> → <code>swmmOutParser</code> → renderizado de <code>results.js</code> (tablas, colores del mapa, deslizador de tiempo, gráficos de perfil/series).</p><h2 id="sistema-de-modulos-y-globales" tabindex="-1">Sistema de módulos y globales <a class="header-anchor" href="#sistema-de-modulos-y-globales" aria-label="Permalink to &quot;Sistema de módulos y globales&quot;">​</a></h2><p>No hay <strong>módulos ES, bundler ni <code>import</code>/<code>export</code></strong>. Cada archivo es un script clásico envuelto en un IIFE. Los módulos se comunican exclusivamente a través de globales adjuntas a <code>window</code>. <strong>El orden de los scripts en <code>index.html</code> es el contrato de dependencias</strong> (<code>index.html:779-810</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config.js → mapbox/proj4/shp/dxf/poly2tri/geotiff (CDN)</span></span>
<span class="line"><span>→ inpParser → inpExporter → network → swmmOutParser → street_view_overlay</span></span>
<span class="line"><span>→ swmm6wasm → results → importers → app → tools → profile → plot</span></span>
<span class="line"><span>→ vendor/triangle → mesh2dProj → mesh2dPslg → mesh2dTerrain → mesh2dTriangle</span></span>
<span class="line"><span>→ mesh2dCoupling → mesh2dExport → mesh2dRender → meshGlLayer → mesh2d</span></span>
<span class="line"><span>→ mesh2dInp → mesh2dDialog → layerTree → landcover → curves → lid → quality</span></span>
<span class="line"><span>→ aquifer → snowpack → ui          (ui.js LAST — it wires every button)</span></span></code></pre></div><p>Los singletons globales principales:</p><table tabindex="0"><thead><tr><th>Global</th><th>Dueño de</th><th>Definido en</th></tr></thead><tbody><tr><td><code>window.map</code></td><td>Instancia <code>Map</code> de Mapbox GL</td><td><code>app.js:38</code></td></tr><tr><td><code>window.App</code></td><td>Estado de UI/app (<code>currentStyle</code>, flags de visibilidad, Set <code>selection</code>, <code>lastRunReport</code>, <code>results2D</code>, <code>outData</code>, …)</td><td><code>app.js:44-58</code></td></tr><tr><td><code>window.Net</code></td><td>Instancia de la clase <code>Network</code> — <strong>fuente única de verdad</strong> de todos los datos del modelo + deshacer/rehacer + autoguardado</td><td><code>network.js:942</code></td></tr><tr><td><code>window.Tools</code></td><td>Máquina de estados de herramientas (selección, dibujo, hit-testing, arrastre)</td><td><code>tools.js:291</code></td></tr><tr><td><code>window.LayerTree</code></td><td>Visibilidad/opacidad de las capas de la malla 2D</td><td><code>layerTree.js:38</code></td></tr><tr><td><code>window.ResultStyling</code></td><td>Motor de coloreado de los resultados de simulación</td><td><code>results.js:547</code></td></tr><tr><td><code>window.AnimationUI</code></td><td>Reproducir/pausa del deslizador de tiempo</td><td><code>ui.js:1086</code></td></tr><tr><td><code>window.CONFIG</code></td><td>Claves de API</td><td><code>config.js</code></td></tr><tr><td><code>window.inpParser</code> / <code>window.inpExporter</code></td><td>Parse / serialización INP</td><td><code>inpParser.js:555</code>, <code>inpExporter.js</code></td></tr><tr><td><code>window.SWMMOutParser</code></td><td>Parser del binario <code>.out</code></td><td><code>swmmOutParser.js</code></td></tr><tr><td><code>window.Mesh2D…</code> / <code>window.TriangleWASM</code> / <code>window.Mesh2DLayers</code> / <code>window.Mesh2DGL</code></td><td>Subsistema 2D</td><td>ver el subsistema de malla 2D y WebGPU</td></tr><tr><td>Editores de módulo (lazy)</td><td><code>CurveEditor</code>, <code>LIDControls</code>, <code>QualityEditor</code>, <code>AquiferEditor</code>, <code>SnowpackEditor</code>, <code>TimeSeriesPlot</code>, <code>ProfilePlot</code>, <code>StreetViewOverlay</code>, <code>Importers</code></td><td>—</td></tr></tbody></table><p>Consecuencias de este diseño:</p><ul><li><strong>El estado se comparte por convención.</strong> <code>tools.js:8-9</code> y <code>ui.js:7-8</code> capturan <code>window.map</code>/<code>window.App</code> en tiempo de carga, por lo que <code>ui.js</code> debe cargar después de <code>app.js</code>.</li><li><strong>Agregar un módulo</strong> significa agregar una etiqueta <code>&lt;script&gt;</code> en la posición correcta de <code>index.html</code> y exponer globales; no hay grafo de imports que el tooling pueda validar.</li><li><strong>El renderizado es de doble vía:</strong> <code>Net</code> es dueño de la geometría + deshacer + persistencia (datos); <code>App</code> + Mapbox son dueños del estado de vista. El <strong>feature-state</strong> de Mapbox (<code>selected</code>, <code>hovered</code>, <code>resultColor</code>) es el puente entre ambos (<code>app.js:320-325</code>).</li></ul><h2 id="cascara-de-ui-—-index-html" tabindex="-1">Cáscara de UI — <code>index.html</code> <a class="header-anchor" href="#cascara-de-ui-—-index-html" aria-label="Permalink to &quot;Cáscara de UI — \`index.html\`&quot;">​</a></h2><p>Toda la app es un grid CSS <code>#app-grid</code> (<code>styles.css:59-73</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grid-template-areas:</span></span>
<span class="line"><span>  &quot;toolbar toolbar toolbar&quot;</span></span>
<span class="line"><span>  &quot;palette map     panel&quot;</span></span>
<span class="line"><span>  &quot;status  status  status&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Contenedor</th><th>ID</th><th>Contenido</th></tr></thead><tbody><tr><td>Barra de herramientas</td><td><code>#toolbar</code></td><td>Deshacer/Rehacer · Guardar/Cargar(dropdown)/Exportar-INP · Opciones · Mesh2D · Gráfico-TS · <strong>Run</strong> · Limpiar · Menú de datos (Curvas/LID/Calidad/Acuífero/Nieve/Malla 2D)</td></tr><tr><td>Paleta izquierda</td><td><code>#tool-palette</code></td><td><code>[seleccionar] [eliminar]</code> + herramientas de nodo (nodo de unión, emisario, estanque, divisor) + herramientas de enlace (conducto, bomba, vertedero, orificio) + herramientas de área (subcuenca, pluviómetro)</td></tr><tr><td>Área del mapa</td><td><code>#map-container</code></td><td><code>#map</code>, búsqueda OSM, tarjeta de ajustes del mapa (mapa base / toggles de capas / unidades / fuente DEM / Sample-DEM-all), tarjeta de árbol de capas, pegman de Street View, panel de deslizador de tiempo, modal de perfil, modales de series de tiempo</td></tr><tr><td>Panel derecho</td><td><code>#panel-right</code></td><td>Redimensionable; pestañas <strong>Propiedades / Resultados / Reporte</strong> (<code>#tab-props</code>, <code>#tab-results</code>, <code>#tab-report</code>)</td></tr><tr><td>Barra de estado</td><td><code>#statusbar</code></td><td><code>#sb-tool</code>, <code>#sb-nodes</code>, <code>#sb-links</code>, <code>#sb-subcatchments</code>, <code>#sb-gages</code>, <code>#sb-coords</code></td></tr><tr><td>Modales</td><td><code>.modal-overlay</code>+<code>.modal-box</code></td><td>Opciones, Proyección, Importar-como, Malla-2D (3 pestañas), Estado-de-corrida (+badge minimizado)</td></tr></tbody></table><h2 id="marco-de-ui" tabindex="-1">Marco de UI <a class="header-anchor" href="#marco-de-ui" aria-label="Permalink to &quot;Marco de UI&quot;">​</a></h2><p><strong>Hecho a mano, sin dependencias.</strong> El contenido dinámico es DOM-string + <code>innerHTML</code> (p. ej. el panel de propiedades <code>renderPropsPanel</code>, <code>ui.js:842</code>); todo el cableado es <code>addEventListener</code>. Las clases de componentes recurrentes viven en <code>styles.css</code>:</p><ul><li><code>.tb-btn</code>, <code>.tb-btn-run</code>, <code>.tb-icon-btn</code>, <code>.tb-dropdown</code>(+<code>.open</code>), <code>.tb-pill</code>(+<code>.active</code>)</li><li><code>.tool-btn</code>(+<code>.active</code>, <code>.tool-btn-danger</code>), <code>.tool-divider</code>, <code>.tool-group-label</code></li><li><code>.side-panel</code>, <code>.panel-tabs</code>, <code>.panel-tab</code>(+<code>.active</code>), <code>.tab-badge</code></li><li><code>.modal-overlay</code>, <code>.modal-box</code>, <code>.modal-actions</code></li><li><code>.prop-section-title</code>, <code>.prop-row</code>, <code>.prop-actions</code></li></ul><p><strong>Temas</strong> usa variables CSS (<code>styles.css:6-29</code>): <code>--accent</code>, <code>--danger</code>, <code>--bg-panel</code>, variables de layout <code>--toolbar-h:44px</code>, <code>--statusbar-h:26px</code>, <code>--panel-w:280px</code>, <code>--palette-w:46px</code>. <code>--panel-w</code> se actualiza en runtime durante el redimensionamiento (<code>ui.js:236</code>).</p><p><strong>Sin i18n.</strong> Todos los strings están hardcodeados en inglés. La única &quot;localización&quot; es el formateo de unidades vía <code>const U = (si, us) =&gt; Net.units === &#39;US&#39; ? us : si;</code> (<code>ui.js:564</code>) usado por los formularios de propiedades guiados por esquema (<code>FIELD_DEFS</code>, <code>ui.js:570-736</code>).</p><h2 id="sistema-de-herramientas-—-tools-js" tabindex="-1">Sistema de herramientas — <code>tools.js</code> <a class="header-anchor" href="#sistema-de-herramientas-—-tools-js" aria-label="Permalink to &quot;Sistema de herramientas — \`tools.js\`&quot;">​</a></h2><p>Una única máquina de estados hecha a mano (<code>window.Tools</code>):</p><ul><li>El registro de herramientas mapea los nombres <code>data-tool</code> de la paleta a tipos: <code>NODE_TOOL_TYPES</code> (<code>junction→JUNCTION</code>, <code>outfall→OUTFALL</code>, <code>storage→STORAGE</code>, <code>divider→DIVIDER</code>, <code>raingage→RAINGAGE</code> — <code>tools.js:11-17</code>) y <code>LINK_TOOL_TYPES</code> (<code>conduit</code>, <code>pump</code>, <code>orifice</code>, <code>weir</code>, <code>outlet</code> — <code>tools.js:18-24</code>), más los modos especiales <code>select</code>, <code>subcatchment</code>, <code>delete</code>.</li><li><strong><code>Tools.setTool(name)</code></strong> (<code>tools.js:145-164</code>) cancela el dibujo, conmuta el resaltado de la paleta, actualiza <code>#sb-tool</code>, cambia el cursor del mapa y deshabilita <code>map.doubleClickZoom</code> en modo subcuenca.</li><li><strong>Estado de dibujo:</strong> <code>linkFrom</code> (primer extremo), <code>linkVertices[]</code>, <code>polyVertices[]</code>, <code>dragging</code>.</li><li><strong>Hit-testing:</strong> <code>featureAt(point)</code> ordena nodos &gt; enlaces &gt; subcuencas &gt; malla 2D en una caja de 12 px (<code>tools.js:216-226</code>); <code>snapNodeAt</code> usa una caja de 24 px sobre <code>swmm-nodes-layer</code>, saltándose los pluviómetros para las operaciones hidráulicas (<code>tools.js:228-239</code>).</li><li><strong>Todas las interacciones con el mapa se despachan por un único handler <code>map.on(&#39;click&#39;)</code></strong> (<code>tools.js:295-363</code>) que conmuta según <code>Tools.active</code>: colocación de nodos, dibujo de enlaces (el primer clic debe caer sobre un nodo; los clics siguientes se ajustan), empuje de vértices de subcuenca, eliminar, seleccionar. <code>dblclick</code> termina una subcuenca (<code>tools.js:365-371</code>). <code>mousemove</code> actualiza el borrador fantasma y el popup de hover (<code>tools.js:375-423</code>). <code>mousedown</code> maneja el arrastre de nodos (<code>tools.js:426-470</code>), coalescido en un único paso de deshacer vía <code>Net.commitMove()</code> en mouseup.</li><li><strong>Teclado</strong> (<code>tools.js:473-505</code>): <code>Esc</code> cancela/limpia, <code>Ctrl+Z</code>/<code>Ctrl+Y</code>/<code>Ctrl+Shift+Z</code> deshacer-rehacer, <code>Ctrl+A</code> seleccionar todo, <code>Del</code>/<code>Backspace</code> eliminar, <code>Enter</code> termina una subcuenca.</li></ul><blockquote><p>Agregar una herramienta nueva requiere: una entrada en <code>NODE_TOOL_TYPES</code>/<code>LINK_TOOL_TYPES</code>, una rama en el handler de <code>click</code> y un botón de paleta.</p></blockquote><h2 id="persistencia-de-estado" tabindex="-1">Persistencia de estado <a class="header-anchor" href="#persistencia-de-estado" aria-label="Permalink to &quot;Persistencia de estado&quot;">​</a></h2><ul><li><strong>Autoguardado:</strong> cada <code>Net.emit()</code> dispara <code>scheduleAutosave()</code> (<code>network.js:168</code>), un debounce de 2 s que escribe <code>JSON.stringify(serialize())</code> en <strong>localStorage</strong> bajo la clave <code>openswmm3d.project</code> (<code>network.js:677-701</code>). Si localStorage lanza una excepción (cupo), cae a <strong>IndexedDB</strong> (DB <code>openswmm3d</code>, store <code>kv</code>) (<code>network.js:703-718</code>). La restauración prefiere localStorage y luego IndexedDB (<code>network.js:734-737</code>), condicionada a ≥1 nodo/enlace.</li><li><strong>Guardar / Cargar:</strong> <code>Net.downloadProject()</code> produce un <code>*.oswmm.json</code> pretty-printed (<code>network.js:774-781</code>); la carga pasa por <code>Net.loadState(data, true)</code> (<code>network.js:490-520</code>). Se aceptan tanto archivos JSON como GeoJSON (el GeoJSON se enruta a los diálogos de import/proyección).</li><li><strong>La geometría de los paneles</strong> también se persiste: ancho del panel derecho en <code>localStorage[&#39;panel-w&#39;]</code>, estado del árbol de capas en <code>localStorage[&#39;swmm-2d-layer-tree&#39;]</code> (<code>layerTree.js:8-9</code>).</li></ul>`,32)])])}const b=o(s,[["render",r]]);export{g as __pageData,b as default};
